def main_solution(num):
    denominations = {'$100': 0, '$50': 0, '$20': 0, '$10': 0, '$5': 0, '$2': 0, '$1': 0}
    remaining = num

    while remaining > 0:
        if remaining >= 100:
            denominations['$100'] += 1
            remaining -= 100
        elif remaining >= 50:
            denominations['$50'] += 1
            remaining -= 50
        elif remaining >= 20:
            denominations['$20'] += 1
            remaining -= 20
        elif remaining >= 10:
